from typing import List
class Solution:
    def maxProfit(self, prices: List[int], profits: List[int]) -> int:
        n = len(profits)
        MAXP = 5000
        def build(idxF):
            tree = [0] * (MAXP + 2)
            def upd(i, v):
                while i <= MAXP:
                    if tree[i] < v: tree[i] = v
                    i += i & -i
            def qry(i):
                r = 0
                while i > 0:
                    r = max(r, tree[i]); i -= i & -i
                return r
            res = [0] * n
            order = range(n) if idxF == 0 else range(n - 1, -1, -1)
            for j in order:
                if idxF == 0:
                    res[j] = qry(prices[j] - 1)
                    upd(prices[j], profits[j])
                else:
                    res[j] = qry(MAXP - prices[j])
                    upd(MAXP + 1 - prices[j], profits[j])
            return res
        left = build(0)
        right = build(1)
        ans = -1
        for j in range(n):
            if left[j] and right[j]:
                ans = max(ans, left[j] + profits[j] + right[j])
        return ans

