class Solution {
    static constexpr int MAXP = 5000;
    int t1[MAXP + 2], t2[MAXP + 2];
    void upd(int* t, int i, int v) { for (; i <= MAXP; i += i & -i) t[i] = max(t[i], v); }
    int qry(int* t, int i) { int r = 0; for (; i > 0; i -= i & -i) r = max(r, t[i]); return r; }
public:
    int maxProfit(vector<int>& prices, vector<int>& profits) {
        int n = profits.size();
        memset(t1, 0, sizeof t1); memset(t2, 0, sizeof t2);
        vector<int> left(n), right(n);
        for (int j = 0; j < n; j++) {
            left[j] = qry(t1, prices[j] - 1);
            upd(t1, prices[j], profits[j]);
        }
        for (int j = n - 1; j >= 0; j--) {
            right[j] = qry(t2, MAXP - prices[j]);
            upd(t2, MAXP + 1 - prices[j], profits[j]);
        }
        int ans = -1;
        for (int j = 0; j < n; j++)
            if (left[j] && right[j]) ans = max(ans, left[j] + profits[j] + right[j]);
        return ans;
    }
};

