class Solution {
    private static final int MAXP = 5000;
    private int[] t1 = new int[MAXP + 2], t2 = new int[MAXP + 2];
    private void upd(int[] t, int i, int v) { for (; i <= MAXP; i += i & -i) t[i] = Math.max(t[i], v); }
    private int qry(int[] t, int i) { int r = 0; for (; i > 0; i -= i & -i) r = Math.max(r, t[i]); return r; }
    public int maxProfit(int[] prices, int[] profits) {
        int n = profits.length;
        int[] left = new int[n], right = new int[n];
        for (int j = 0; j < n; j++) {
            left[j] = qry(t1, prices[j] - 1);
            upd(t1, prices[j], profits[j]);
        }
        for (int j = n - 1; j >= 0; j--) {
            right[j] = qry(t2, MAXP - prices[j]);
            upd(t2, MAXP + 1 - prices[j], profits[j]);
        }
        int ans = -1;
        for (int j = 0; j < n; j++)
            if (left[j] > 0 && right[j] > 0) ans = Math.max(ans, left[j] + profits[j] + right[j]);
        return ans;
    }
};

