var maxProfit = function(prices, profits) {
    const n = profits.length, MAXP = 5000;
    const mk = () => new Array(MAXP + 2).fill(0);
    const t1 = mk(), t2 = mk();
    const upd = (t, i, v) => { for (; i <= MAXP; i += i & -i) if (t[i] < v) t[i] = v; };
    const qry = (t, i) => { let r = 0; for (; i > 0; i -= i & -i) r = Math.max(r, t[i]); return r; };
    const left = new Array(n), right = new Array(n);
    for (let j = 0; j < n; j++) {
        left[j] = qry(t1, prices[j] - 1);
        upd(t1, prices[j], profits[j]);
    }
    for (let j = n - 1; j >= 0; j--) {
        right[j] = qry(t2, MAXP - prices[j]);
        upd(t2, MAXP + 1 - prices[j], profits[j]);
    }
    let ans = -1;
    for (let j = 0; j < n; j++)
        if (left[j] > 0 && right[j] > 0) ans = Math.max(ans, left[j] + profits[j] + right[j]);
    return ans;
};
